function go(path: string) { router.push(path === 'login' ? '/login' : '/console/' + path); drawer.value = false }
function toggle(label: string) { expanded.value = expanded.value.includes(label) ? expanded.value.filter(v => v !== label) : [...expanded.value, label] }
function notify(message: string) { if (message === '已全部标为已读') notifications.value = notifications.value.map(item => ({ ...item, unread: false })); if (message === '账号恢复流程即将开放') { router.push('/recovery'); return } toast.value = message; setTimeout(() => toast.value = '', 2800) }
function openDialog(kind: string) { dialog.value = kind }
const systemThemeQuery = window.matchMedia('(prefers-color-scheme: dark)')
function applyTheme(value: Theme) { const dark = value === 'dark' || (value === 'system' && systemThemeQuery.matches); document.documentElement.dataset.theme = value; document.documentElement.classList.toggle('dark', dark); localStorage.setItem(preferenceKey, JSON.stringify({ expanded: expanded.value, theme: value })) }
function handleSystemThemeChange() { if (theme.value === 'system') applyTheme('system') }
function cycleTheme() { theme.value = theme.value === 'system' ? 'light' : theme.value === 'light' ? 'dark' : 'system'; applyTheme(theme.value); notify(`主题：${theme.value === 'system' ? '跟随系统' : theme.value === 'light' ? '浅色' : '深色'}`) }
function submitSearch() { if (!isSearch.value) go('search'); router.replace({ query: query.value ? { q: query.value } : {} }); notify(query.value ? `已搜索：${query.value}` : '已恢复全部结果') }
function handleShortcut(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); go('search'); requestAnimationFrame(() => document.querySelector<HTMLInputElement>('.search-box input')?.focus()) } }
const filteredRows = computed(() => rows.value.filter(row => { const matchesQuery = !query.value || `${row.name} ${row.owner} ${row.status}`.toLowerCase().includes(query.value.toLowerCase()); const matchesStatus = statusFilter.value === '全部状态' || row.status === statusFilter.value; return matchesQuery && matchesStatus }))
function setStatusFilter(value: string) { statusFilter.value = statusFilter.value === value ? '全部状态' : value }
const allVisibleSelected = computed(() => filteredRows.value.length > 0 && filteredRows.value.every(row => selectedRows.value.includes(row.name)))
function toggleRow(name: string) { selectedRows.value = selectedRows.value.includes(name) ? selectedRows.value.filter(item => item !== name) : [...selectedRows.value, name] }
function toggleAll() { selectedRows.value = allVisibleSelected.value ? selectedRows.value.filter(name => !filteredRows.value.some(row => row.name === name)) : [...new Set([...selectedRows.value, ...filteredRows.value.map(row => row.name)])] }
function clearSelection() { selectedRows.value = [] }
const isDashboard = computed(() => currentPath.value === 'dashboard'); const isSearch = computed(() => currentPath.value === 'search')
const isHealth = computed(() => currentPath.value === 'ops/health')
const isUsers = computed(() => currentPath.value === 'security/users')
const isPermissions = computed(() => currentPath.value === 'security/permissions')
const isNotifications = computed(() => currentPath.value === 'communications/notifications')
const isAnnouncements = computed(() => currentPath.value === 'communications/announcements')
const securityStats = [{ label: '活跃用户', value: '24', detail: '最近 7 天有活动', tone: 'teal' }, { label: '已启用 MFA', value: '21', detail: '覆盖率 87.5%', tone: 'primary' }, { label: '待激活', value: '2', detail: '需要发送邀请', tone: 'orange' }, { label: '安全提醒', value: '1', detail: '建议及时处理', tone: 'pink' }]
const permissionGroups = [{ name: '内容与创作', items: [{ key: 'resource.read', label: '读取资源', enabled: true }, { key: 'resource.write', label: '编辑资源', enabled: true }, { key: 'resource.delete', label: '删除资源', enabled: false }] }, { name: '身份与安全', items: [{ key: 'system.user.read', label: '查看用户', enabled: true }, { key: 'system.role.manage', label: '管理角色', enabled: false }, { key: 'system.session.manage', label: '管理会话', enabled: false }] }, { name: '存储管理', items: [{ key: 'storage.provider.manage', label: '管理存储 Provider', enabled: false }, { key: 'resource.download', label: '下载资源', enabled: true }] }]
const stagedPermissions = ref<Record<string, boolean>>({})
const hasStagedPermissions = computed(() => Object.keys(stagedPermissions.value).length > 0)
function togglePermission(key: string, current: boolean) { stagedPermissions.value = { ...stagedPermissions.value, [key]: !current } }
function discardPermissions() { stagedPermissions.value = {}; notify('已放弃权限修改') }
function reviewPermissions() { dialog.value = 'permission-review' }
function applyPermissions() { stagedPermissions.value = {}; dialog.value = ''; notify('权限修改已提交并写入审计') }
const services = [{ name: 'Application / API', status: '健康', latency: '42 ms', icon: '◇' }, { name: 'PostgreSQL', status: '健康', latency: '8 ms', icon: '▣' }, { name: '持久化存储', status: '健康', latency: '116 ms', icon: '▥' }, { name: 'Scheduler / Worker', status: '降级', latency: '队列 12', icon: '◷' }]
const alerts = [{ severity: 'warning', name: '备份任务延迟', component: 'Scheduler / Worker', condition: '队列深度 > 10', time: '2 小时前' }, { severity: 'info', name: '存储容量提醒', component: '持久化存储', condition: '使用率 68%', time: '昨天' }]
const notifications = ref([{ title: '备份任务执行失败', text: '每周资料备份需要你的关注', time: '2 小时前', type: 'error', unread: true }, { title: '资源同步完成', text: '12 个资源的元数据已更新', time: '昨天', type: 'success', unread: true }, { title: '系统健康检查', text: '所有核心服务运行正常', time: '昨天', type: 'info', unread: false }])
const notificationTab = ref('全部')
const unreadNotificationCount = computed(() => notifications.value.filter(item => item.unread).length)
const visibleNotifications = computed(() => notifications.value.filter(item => notificationTab.value === '全部' || (notificationTab.value === '未读' && item.unread) || (notificationTab.value === '系统' && item.type === 'info')))
function markNotificationRead(title?: string) { notifications.value = notifications.value.map(item => title && item.title !== title ? item : { ...item, unread: false }); notify(title ? '已标记为已读' : '已全部标为已读') }
const announcements = [{ title: 'Ikaros Console 维护通知', audience: '全部用户', status: '已发布', publishedAt: '2026-09-01 18:00', expiresAt: '2026-09-08 18:00', tone: 'info' }, { title: '新版本媒体索引已上线', audience: '内容创作者', status: '已发布', publishedAt: '2026-08-28 09:30', expiresAt: '长期有效', tone: 'success' }, { title: '存储策略调整预告', audience: '管理员', status: '草稿', publishedAt: '未发布', expiresAt: '—', tone: 'warning' }]
const announcementTab = ref('全部')
const visibleAnnouncements = computed(() => announcements.filter(item => announcementTab.value === '全部' || item.status === announcementTab.value))
const isLogin = computed(() => route.path === '/login'); const loginEmail = ref(''); const loginPassword = ref(''); const rememberLogin = ref(true); const loginError = ref('')
function submitLogin() { loginError.value = ''; if (!loginEmail.value.trim()) { loginError.value = '请输入用户名或邮箱'; return } if (loginPassword.value.length < 6) { loginError.value = '密码至少需要 6 位'; return } router.push('/console/dashboard'); notify('登录成功，欢迎回来') }
const kpis = [{ label: '资源', value: '12,486', trend: '+8.4%', icon: '◈', tone: 'primary' }, { label: '存储', value: '68.4 GB', trend: '已配置 100 GB', icon: '▥', tone: 'teal' }, { label: '今天', value: '8 / 12', trend: '4 项待完成', icon: '✓', tone: 'orange' }, { label: '后台任务', value: '3', trend: '1 项失败', icon: '⇄', tone: 'purple' }, { label: '通知', value: '6', trend: '2 条重要', icon: '✉', tone: 'pink' }]
const activities = [{ icon: '✦', text: '完成了媒体资源的元数据同步', target: '《星际穿越》', time: '12 分钟前', color: 'purple' }, { icon: '✓', text: '完成任务', target: '整理本周阅读清单', time: '1 小时前', color: 'teal' }, { icon: '↗', text: '更新了项目', target: 'Ikaros V2 产品设计', time: '昨天 18:24', color: 'orange' }, { icon: '♧', text: '收藏了资源', target: 'Material Design 3', time: '昨天 15:08', color: 'blue' }]
const resources = [{ name: '《星际穿越》', type: '电影', tags: ['科幻', '收藏'], status: '进行中', progress: 72, updated: '12 分钟前' }, { name: 'Ikaros V2 产品设计', type: '文档', tags: ['项目'], status: '已更新', progress: 100, updated: '昨天' }, { name: 'Material Design 3', type: '网页', tags: ['设计系统'], status: '收藏', progress: 34, updated: '3 天前' }, { name: '2026 年读书计划', type: '集合', tags: ['计划'], status: '草稿', progress: 18, updated: '5 天前' }]
type TableRow = { id?: string; name: string; owner: string; status: string; updated: string }
const rows = ref<TableRow[]>([{ id: 'demo-backup', name: '媒体资源索引', owner: '系统', status: '已启用', updated: '刚刚' }, { id: 'demo-weekly-backup', name: '每周资料备份', owner: '你', status: '运行中', updated: '8 分钟前' }, { id: 'demo-reading-sync', name: '阅读进度同步', owner: '你', status: '已暂停', updated: '昨天' }, { id: 'demo-storage-health', name: '存储健康检查', owner: '系统', status: '已启用', updated: '昨天' }, { id: 'demo-weekly-report', name: '活动周报', owner: '你', status: '失败', updated: '2 天前' }])
const demoRows = rows.value
const actorId = String(import.meta.env.VITE_ACTOR_ID || '')
async function loadResources() {
  if (isDashboard.value) return
  loading.value = true
  errorState.value = null
  try {
    if (currentPath.value === 'library') {
      const result = unwrapPage(await api.listResources('?limit=5'))
      if (result.length) rows.value = result.map(item => ({ name: item.title || `Resource ${item.id.slice(0, 8)}`, owner: '当前用户', status: item.lifecycle || '已启用', updated: item.updated_at ? new Date(item.updated_at).toLocaleString('zh-CN') : '刚刚' }))
    } else if (currentPath.value === 'security/users') {
      const result = unwrapPage(await api.listUsers('?page=0&size=5'))
      if (result.length) rows.value = result.map(item => ({ name: item.display_name || item.username || item.id.slice(0, 8), owner: item.username || '平台用户', status: item.status || 'ACTIVE', updated: item.last_active_at ? new Date(item.last_active_at).toLocaleString('zh-CN') : '暂无记录' }))
    } else if (currentPath.value === 'ops/background') {
      const result = await api.listBackgroundTasks()
      if (result.length) rows.value = result.slice(0, 5).map(item => ({ id: item.id, name: item.task_type || item.id.slice(0, 8), owner: item.owning_subsystem || '系统', status: item.state || '排队中', updated: item.created_at ? new Date(item.created_at).toLocaleString('zh-CN') : '刚刚' }))
    } else if (currentPath.value === 'security/permissions') {
      const result = await api.listRoles()
      if (result.length) rows.value = result.slice(0, 5).map(item => ({ name: item.name || item.code || item.id.slice(0, 8), owner: `${item.permissions?.length || 0} 项权限`, status: item.builtIn ? '系统角色' : '自定义角色', updated: '权限注册表' }))
    } else if (currentPath.value === 'storage/tiers') {
      const result = await api.listStorageProviders()
      if (result.length) rows.value = result.slice(0, 5).map(item => ({ name: item.providerKey || item.id.slice(0, 8), owner: `${item.providerType || '存储'} · ${item.tier || '默认层'}`, status: item.status || 'DISABLED', updated: item.updatedAt ? new Date(item.updatedAt).toLocaleString('zh-CN') : '刚刚' }))
    } else if (currentPath.value === 'drive' || currentPath.value === 'drive/spaces') {
      const result = await api.listDriveSpaces(actorId)
      if (result.length) rows.value = result.slice(0, 5).map(item => ({ id: item.id, name: item.name || `Drive Space ${item.id.slice(0, 8)}`, owner: '当前用户', status: item.status || 'ACTIVE', updated: item.updated_at ? new Date(item.updated_at).toLocaleString('zh-CN') : '刚刚' }))
    } else if (currentPath.value === 'planning/today') {
      const result = await api.listTodayTasks(actorId)
      if (result.length) rows.value = result.slice(0, 5).map(item => ({ id: item.id, name: item.title || `Task ${item.id.slice(0, 8)}`, owner: item.priority || '普通', status: item.status || 'OPEN', updated: item.due_at ? new Date(item.due_at).toLocaleString('zh-CN') : '今天' }))
    } else return
    apiConnected.value = true
  } catch (error) {
    apiConnected.value = false
    if (error instanceof ApiError && [401, 403, 404, 409, 412].includes(error.status)) {
      errorState.value = { status: error.status, title: error.status === 401 ? '会话已失效' : error.status === 403 ? '你没有权限访问此页面' : error.status === 404 ? '页面或资源不存在' : '数据发生并发冲突', detail: error.problem?.detail || error.message }
    } else { rows.value = demoRows; notify('后端暂不可用，已保留演示数据') }
  } finally { loading.value = false }
}
onMounted(loadResources); watch(currentPath, loadResources)
onMounted(() => applyTheme(theme.value)); watch(expanded, () => applyTheme(theme.value), { deep: true })
watch(() => route.query.q, value => { query.value = String(value || '') })
onMounted(() => window.addEventListener('keydown', handleShortcut)); onBeforeUnmount(() => window.removeEventListener('keydown', handleShortcut))
onMounted(() => systemThemeQuery.addEventListener('change', handleSystemThemeChange)); onBeforeUnmount(() => systemThemeQuery.removeEventListener('change', handleSystemThemeChange))
let refreshTimer: number | undefined
watch(currentPath, value => {
  if (refreshTimer) window.clearInterval(refreshTimer)
  if (value === 'ops/background') refreshTimer = window.setInterval(loadResources, 30000)
}, { immediate: true })
onBeforeUnmount(() => { if (refreshTimer) window.clearInterval(refreshTimer) })
function genericTitle() { return current.value.label }
async function bulkTaskAction(action: 'cancel' | 'retry') {
  if (currentPath.value !== 'ops/background') { dialog.value = ''; notify('已打开批量操作'); return }
  if (action === 'retry') { dialog.value = ''; notify('已提交重试请求'); return }
  const targets = rows.value.filter(row => selectedRows.value.includes(row.name) && row.id && !row.id.startsWith('demo-'))
  try { await Promise.all(targets.map(row => api.cancelBackgroundTask(row.id!))); dialog.value = ''; clearSelection(); await loadResources(); notify(`${targets.length || selectedRows.value.length} 项任务已取消`) } catch (error) { notify(error instanceof Error ? error.message : '取消任务失败') }
}
